  // --- root files ---
  add('global.json', `{\n  "sdk": { "version": "8.0.100", "rollForward": "latestMajor" }\n}\n`);
  add('.gitignore', `bin/\nobj/\n.vs/\n*.user\nappsettings.*.local.json\n.env\n`);

  // --- solution: always rebuilt from the .csproj files that really exist ---
  tree.splice(0, tree.length, ...tree.filter(t => !(rel(t).endsWith('.sln') && !rel(t).includes('/'))));
  const csprojs = tree.map(rel).filter(p => p.endsWith('.csproj')).sort();
